package com.desktodo.app;
import android.app.*;import android.os.*;import org.json.*;import java.time.*;
/** Repeat rules and undo fixtures only. Never contacts a device or invokes Wi-Fi pairing. */
public final class RepeatChecks extends Instrumentation {
 int count;void check(boolean b,String why){count++;if(!b)throw new AssertionError(why);}interface Job{void run()throws Exception;}void rejects(Job job,String why)throws Exception{boolean caught=false;try{job.run();}catch(Exception e){caught=true;}check(caught,why);}
 @Override public void onCreate(Bundle b){start();}
 @Override public void onStart(){Bundle out=new Bundle();try{Instant now=Instant.parse("2026-01-31T01:00:00Z");JSONObject base=DeskModel.task("交月报",now.toString()).put("id","fixture-series");JSONObject monthly=RepeatRules.configure(base,"monthly"),feb=RepeatRules.next(monthly,now);check(RepeatRules.fingerprint(monthly).equals("a386114657f1982729854c5111e400a9d82eba537fde2b5272ba54755616d765"),"cross-client fingerprint contract");check(RepeatRules.sameDay("2026-02-28T01:00:00Z","2026-02-28T02:00:00Z"),"time edit preserves month-end anchor");check(feb.getString("due").equals("2026-02-28T01:00:00Z"),"Jan31 clamps to Feb28");JSONObject march=RepeatRules.next(feb,Instant.parse("2026-02-28T01:00:00Z"));check(march.getString("due").equals("2026-03-31T01:00:00Z"),"anchor31 restored in March");check(RepeatRules.next(RepeatRules.configure(DeskModel.copy(base).put("due","2028-01-31T01:00:00Z"),"monthly"),Instant.parse("2028-01-31T01:00:00Z")).getString("due").startsWith("2028-02-29"),"leap February");
 JSONObject friday=RepeatRules.configure(DeskModel.copy(base).put("due","2026-10-16T01:00:00Z"),"weekdays");check(RepeatRules.next(friday,Instant.parse("2026-10-16T01:00:00Z")).getString("due").startsWith("2026-10-19"),"weekend skipped");JSONObject daily=RepeatRules.configure(base,"daily");JSONObject catchup=RepeatRules.next(daily,Instant.parse("2026-10-18T08:00:00Z"));check(catchup.getString("due").equals("2026-10-19T01:00:00Z"),"late completion one future occurrence, no backlog");check(RepeatRules.next(daily,now).getString("id").equals("fixture-series:2026-02-01"),"deterministic next id");
 JSONArray tasks=new JSONArray().put(monthly);RepeatRules.Result done=RepeatRules.finish(tasks,0,now,false);check(done.active.length()==1&&done.record.getString("recordType").equals("completed"),"replace only completed occurrence");check(RepeatRules.restore(done.active,done.record).getJSONObject(0).getString("id").equals("fixture-series"),"undo removes untouched next occurrence");JSONArray edited=DeskModel.copy(done.active);edited.getJSONObject(0).put("title","另一端已改名");rejects(()->RepeatRules.restore(edited,done.record),"undo cannot erase modified future task");rejects(()->RepeatRules.restore(new JSONArray(),done.record),"undo cannot resurrect handled future occurrence");RepeatRules.Result skipped=RepeatRules.finish(tasks,0,now,true);check(ScreenData.weekCount(new JSONArray().put(skipped.record),now)==0,"skip never counts as completion");check(skipped.active.getJSONObject(0).getString("id").equals(done.active.getJSONObject(0).getString("id")),"skip uses same next id");rejects(()->RepeatRules.configure(DeskModel.task("无日期",null),"daily"),"repeat requires due date");check(!RepeatRules.configure(monthly,"none").has("repeatRule"),"disable repeat");
 check(java.util.Base64.getDecoder().decode(SetupPanel.cityBitmap("苏州")).length==320,"city bitmap exact size");check(java.util.Base64.getDecoder().decode(SetupPanel.cityBitmap("很长的城市名称也必须被裁剪")).length==320,"long city clipped to bounds");out.putString("stream","PASS: "+count+" repeat/setup contracts: month anchor/leap/weekdays, deterministic IDs, no backlog, undo conflict, skip statistics and city assets\n");finish(Activity.RESULT_OK,out);}catch(Throwable e){out.putString("stream","FAIL: "+e+"\n");finish(Activity.RESULT_CANCELED,out);}}
}
